"""Render the reviewed real-chat campaign as a self-contained HTML appendix."""
from pathlib import Path
import hashlib,json,math,statistics,html,re
from collections import Counter
from markdown_it import MarkdownIt
ROOT=Path(__file__).resolve().parents[1];P=ROOT/'eval_results/technical/chat-baseline-20261015'
md=MarkdownIt('commonmark',{'html':False}).enable('table')
def load(n):return json.loads((P/n).read_text())
def pct(xs,p):return sorted(xs)[max(0,math.ceil(len(xs)*p)-1)] if xs else None
def stats(rows):
 xs=[r['elapsed_seconds'] for r in rows]
 return {'n':len(rows),'median_seconds':statistics.median(xs) if xs else None,'p95_nearest_rank_seconds':pct(xs,.95),'min_seconds':min(xs) if xs else None,'max_seconds':max(xs) if xs else None}
def main():
 pack=load('questions-final.json');run=load('results.json');review=load('review.json');runtime=load('server/runtime.json');spending=load('server/spending.json')
 assert run['completed'];assert run['questions_sha256']==hashlib.sha256((P/'questions-final.json').read_bytes()).hexdigest()
 lookup={x['key']:x for x in review['grades']};events=[]
 for p in (P/'server').glob('*.json'):
  x=json.loads(p.read_text())
  if 'question' in x:events.append(x)
 rows=[]
 for r in run['results']:
  key=f"{r['pass']}/{r['id']}/{r['turn']}";grade=lookup[key];matches=[e for e in events if e['question']==r['question'] and e.get('answer')==r.get('answer') and e['started_at']>=r['started_at']]
  assert matches,key
  e=min(matches,key=lambda e:e['started_at']);m=e.get('metadata',{});rows.append({**r,**grade,'trace_id':e['id'],'route':m.get('_catalog_route'),'evidence':m.get('_catalog_evidence'),'generation':m.get('_catalog_generation'),'server_seconds':e['server_seconds'],'http_calls':e['http_calls']})
 first=[r for r in rows if r['pass']=='first'];unseen=[r for r in first if r['group']=='unseen'];known=[r for r in first if r['group']=='known'];repeat=[r for r in rows if r['pass']=='warm_repeat'];rag=[r for r in first if (r['evidence'] or {}).get('retrieval_executed')]
 metrics={'quality_unseen':dict(Counter(r['verdict'] for r in unseen)),'quality_known':dict(Counter(r['verdict'] for r in known)),'latency_first':stats(first),'latency_unseen':stats(unseen),'latency_first_excluding_first_load':stats(first[1:]),'latency_warm_repeat':stats(repeat),'latency_rag_first':stats(rag),'latency_without_rag_first':stats([r for r in first if r not in rag]),'routes_first':dict(Counter(r['route'] for r in first)),'retrieval_turns_first':len(rag),'generation_attempts_first':sum(bool((r['generation'] or {}).get('call_attempted')) for r in first),'generation_published_first':sum(bool((r['generation'] or {}).get('published')) for r in first),'generation_errors_first':dict(Counter((r['generation'] or {}).get('error') for r in first if (r['generation'] or {}).get('error'))),'remote_calls':len(spending['records']),'reported_cost_usd':sum(x.get('reported_cost_usd',0) for x in spending['records']),'conservative_debit_usd':spending['debit_usd'],'api_errors':sum(bool(r.get('error')) for r in rows)}
 metrics['latency_satisfactory_unseen']=stats([r for r in unseen if r['verdict'] in ['correct','justified_limit']])
 metrics['latency_failed_unseen']=stats([r for r in unseen if r['verdict']=='failure'])
 metrics['required_field_additions_first']=sum(d['selection_reason']=='required_field' for r in rag for ss in r['evidence']['sources'] for d in ss['passages'])
 metrics['quality_by_category_unseen']={c:dict(Counter(r['verdict'] for r in unseen if r['category']==c)) for c in sorted(set(r['category'] for r in unseen))}
 bundle={'protocol':pack['protocol'],'questions_sha256':run['questions_sha256'],'runtime':runtime,'metrics':metrics,'review':review,'results':rows}
 (P/'summary.json').write_text(json.dumps(metrics,ensure_ascii=False,indent=2)+'\n')
 (P/'reviewed-results.json').write_text(json.dumps(bundle,ensure_ascii=False,indent=2)+'\n')
 esc=html.escape;labels={'correct':'Correcte','justified_limit':'Limite pertinente','partial':'Partielle','failure':'Échec'}
 satisfactory=metrics['quality_unseen'].get('correct',0)+metrics['quality_unseen'].get('justified_limit',0)
 cards=[]
 for r in rows:
  refs=[]
  for k in r.get('object_ids',[]):
   e=pack['reference_evidence'].get(k)
   if e:refs.append(f'<li><a href="{esc(e["source_url"],quote=True)}" target="_blank" rel="noreferrer">{esc(e["identity"]["raw_name"])}</a></li>')
  passages=[]
  for s in (r.get('evidence') or {}).get('sources',[]):
   for d in s.get('passages',[]):passages.append(f'<li><b>{esc(s["brand"]+" "+s["model"])} · {s["year"]} · {esc(d["section"])} · rang {d["rank"]}</b><p>{esc(d["original_text"])}</p></li>')
  facts=f'<details><summary>Références annotées ({len(refs)})</summary><ul>{"".join(refs)}</ul></details>' if refs else ''
  proof=f'<details><summary>Passages livrés à la réponse ({len(passages)})</summary><ul class="passages">{"".join(passages)}</ul></details>' if passages else ''
  group='repeat' if r['pass']=='warm_repeat' else r['group'];meta=f'{r["id"]} · tour {r["turn"]} · {r["category"]}'
  cards.append(f'''<article class="case" data-group="{group}" data-verdict="{r['verdict']}"><div class="case-top"><span>{esc(meta)}</span><span class="badge {r['verdict']}">{labels[r['verdict']]}</span><strong>{r['elapsed_seconds']:.2f} s</strong></div><h3>{esc(r['question'])}</h3><p class="review">{esc(r['note'])}</p><details><summary>Réponse réellement reçue</summary><div class="answer">{md.render(r.get('answer') or r.get('error',''))}</div></details><details><summary>Attendu figé avant le test</summary><p>{esc(r['expected'])}</p></details>{facts}{proof}<small>Parcours : {esc(r['route'] or 'non exposé')} · serveur {r['server_seconds']:.2f} s · {len(r['http_calls'])} appel(s) distant(s).</small></article>''')
 table=[]
 for label,k in [('Première passe, tous les tours','latency_first'),('Demandes inédites','latency_unseen'),('Réponses satisfaisantes, inédites','latency_satisfactory_unseen'),('Échecs, demandes inédites','latency_failed_unseen'),('Première passe hors chargement initial','latency_first_excluding_first_load'),('Tours avec recherche BGE','latency_rag_first'),('Tours sans recherche BGE','latency_without_rag_first'),('Six répétitions prévues','latency_warm_repeat')]:
  v=metrics[k];table.append(f'<tr><th>{label}</th><td>{v["n"]}</td><td>{v["median_seconds"]:.2f} s</td><td>{v["p95_nearest_rank_seconds"]:.2f} s</td><td>{v["max_seconds"]:.2f} s</td></tr>')
 issues=''.join(f'<li><b>{esc(x["title"])}</b><p>{esc(x["detail"])}</p></li>' for x in review['findings'])
 screenshots=''.join(f'<tr><th>{esc(x["question"])}</th><td>{esc(x["scope"])}</td><td>{esc(x["assessment"])}</td></tr>' for x in review['screenshots'])
 limits=''.join(f'<li>{esc(x)}</li>' for x in review['limitations'])
 plural_labels={'correct':'réponses correctes','justified_limit':'limites pertinentes','partial':'réponse partielle','failure':'échecs'}
 outcomes=''.join(f'<span class="quality {k}"><b>{metrics["quality_unseen"].get(k,0)}</b> {plural_labels[k]}</span>' for k,v in labels.items())
 raw=json.dumps(bundle,ensure_ascii=False).replace('<','\\u003c')
 page='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bikefinder · Le vrai chat à l’épreuve</title><style>
:root{--bg:#f5f4ed;--card:#fffefa;--ink:#24343e;--muted:#62716f;--line:#d9dfd5;--green:#347366;--gold:#e7b542;--red:#a14435}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:17px/1.65 system-ui,sans-serif}main{max-width:1180px;margin:auto;padding:44px 26px 80px}a{color:var(--green);text-underline-offset:3px}nav,.eyebrow{font-size:13px;text-transform:uppercase;letter-spacing:.14em;color:var(--muted)}header{padding:32px 0 20px;border-bottom:1px solid var(--line)}h1{font-size:clamp(38px,6vw,66px);letter-spacing:-.045em;line-height:1.05;margin:18px 0 24px;max-width:900px}h2{font-size:30px;line-height:1.2;letter-spacing:-.025em;margin:40px 0 16px}h3{font-size:20px;line-height:1.4}.lede{font-size:21px;max-width:900px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:28px 0}.metric{padding:22px;border:1px solid var(--line);border-radius:18px;background:var(--card)}.metric b{font-size:36px;line-height:1.1;display:block}.metric span{display:block;font-size:14px;color:var(--muted);margin-top:12px}.note{border-left:4px solid var(--gold);padding:18px 22px;background:#fff6df;border-radius:4px 14px 14px 4px}.quality{display:inline-block;margin:5px 12px 5px 0;padding:7px 12px;border-radius:8px;font-size:14px;background:white}.quality b{font-size:22px}table{border-collapse:collapse;width:100%;font-size:15px;background:var(--card)}th,td{border:1px solid var(--line);padding:14px;text-align:left;vertical-align:top}thead th{background:#e9ede5}.table-wrap{overflow:auto}li p{margin:6px 0 20px}.filters{display:flex;flex-wrap:wrap;gap:10px;margin:20px 0;position:sticky;top:0;background:var(--bg);padding:12px 0;z-index:1}input,select,button{font:inherit;padding:10px 14px;border:1px solid var(--line);border-radius:9px;background:white;color:var(--ink)}input{flex:1;min-width:210px}button{cursor:pointer}.case{padding:24px;margin:16px 0;background:var(--card);border:1px solid var(--line);border-radius:18px}.case-top{display:flex;gap:12px;align-items:center;font-size:13px;color:var(--muted);flex-wrap:wrap}.case-top strong{margin-left:auto;font-size:18px;color:var(--ink)}.badge{padding:3px 10px;border-radius:20px;background:#eef1ea}.correct,.justified_limit{color:#266b55}.failure{color:var(--red)}.partial{color:#93600b}.review{font-weight:550}.answer{background:#f5f6f2;padding:18px;border-radius:10px;overflow:auto;font-size:15px}.answer h3{font-size:18px}.answer table{min-width:440px}details{margin:12px 0}summary{cursor:pointer;color:var(--green);font-weight:600}small{font-size:12px;color:var(--muted)}.passages{font-size:14px}footer{margin-top:40px;padding-top:22px;border-top:1px solid var(--line);color:var(--muted);font-size:13px}[hidden]{display:none!important}@media(max-width:700px){main{padding:22px 16px}.metrics{grid-template-columns:1fr 1fr}.metric b{font-size:29px}.case{padding:18px}.table-wrap table{min-width:650px}}@media print{.filters,button,nav{display:none}details{display:block}.case{break-inside:avoid}}
</style><main><nav>Bikefinder / Annexe de validation / 15 octobre 2026</nav><header><div class="eyebrow">BGE-M3 d’origine · SQL + Jev + Mistral local</div><h1>Le vrai chat<br>à l’épreuve des questions.</h1><p class="lede">__CONCLUSION__</p></header><div class="metrics"><div class="metric"><b>__SCORE__/36</b><span>réponses satisfaisantes sur les demandes inédites, limites pertinentes comprises</span></div><div class="metric"><b>__MEDIAN__ s</b><span>temps médian sur les 36 demandes inédites</span></div><div class="metric"><b>__RAG__/42</b><span>tours de la première passe ayant réellement utilisé BGE-M3</span></div><div class="metric"><b>__COST__ $</b><span>coût distant retourné ; plafond autorisé 0,50 $</span></div></div><div>__OUTCOMES__</div><p class="note">Première passe conservée sans correction du chat : 24 questions isolées + 6 dialogues de deux tours, 5 cas connus issus des captures (6 tours), puis 6 répétitions prévues. Ce lot exploratoire rédigé et relu par le même agent ne constitue pas une validation humaine indépendante.</p><h2>Ce que les erreurs nous apprennent</h2><ol>__ISSUES__</ol><h2>Les questions de tes captures ont-elles leur place ?</h2><div class="table-wrap"><table><thead><tr><th>Demande</th><th>Dans le périmètre ?</th><th>Ce que le chat devrait faire</th></tr></thead><tbody>__SCREENSHOTS__</tbody></table></div><h2>Temps réellement observés</h2><div class="table-wrap"><table><thead><tr><th>Population</th><th>Tours</th><th>Médiane</th><th>P95</th><th>Maximum</th></tr></thead><tbody>__TIMES__</tbody></table></div><p>Durée de la soumission à la réponse complète via l’API Gradio utilisée par l’interface. Le temps de création du client est conservé séparément. Le P95 est le rang supérieur sur ce petit lot, pas une garantie de service. Les caches existants sont conservés ; « répété » ne signifie pas que tout le calcul est évité.</p><p>__TIMING_NOTE__</p><h2>Chaque question, sans masquer les échecs</h2><div class="filters"><select id="group" aria-label="Lot"><option value="unseen">Questions inédites</option><option value="known">Cas des captures</option><option value="repeat">Répétitions</option><option value="all">Tous les essais</option></select><select id="verdict" aria-label="Résultat"><option value="all">Tous les résultats</option><option value="failure">Échecs</option><option value="partial">Réponses partielles</option><option value="correct">Correctes</option><option value="justified_limit">Limites pertinentes</option></select><input id="search" placeholder="Chercher une moto, une question…" aria-label="Rechercher"><button id="download">Exporter les résultats</button></div><p id="count" aria-live="polite"></p><div id="cases">__CARDS__</div><h2>Protocole et limites</h2><ul>__LIMITS__</ul><p>Le processus de test charge le même point d’entrée Gradio que l’application, à partir du commit <code>__COMMIT__</code>. Il fixe le mode rapide et BGE-M3 <code>5617a9f…</code>, sans adaptateur LoRA. Les enveloppes d’observation enregistrent les résultats et plafonnent les appels Jev ; elles ne changent ni les prompts ni les décisions. L’ancienne session sur le port 7860 reste intacte.</p><p>Coût conservateur, réservations non soldées comprises : __DEBIT__ $. Tarification de référence vérifiée le 15 octobre : <a href="https://openrouter.ai/typesafe/jev-1.13/api">Jev 1.13 sur OpenRouter</a>. BGE et Mistral tournent localement ; énergie et amortissement non mesurés.</p><footer>Rapport local. Sources annotées avant les essais ; verdicts relus après exécution. Empreinte du lot : <code>__HASH__</code>. Les fiches Motoplanète restent les références du catalogue, sans validation indépendante auprès du constructeur.</footer></main><script id="data" type="application/json">__DATA__</script><script>const cards=[...document.querySelectorAll('.case')],group=document.querySelector('#group'),verdict=document.querySelector('#verdict'),search=document.querySelector('#search');function filter(){let n=0;for(const c of cards){const keep=(group.value==='all'||c.dataset.group===group.value)&&(verdict.value==='all'||c.dataset.verdict===verdict.value)&&c.textContent.toLocaleLowerCase('fr').includes(search.value.toLocaleLowerCase('fr'));c.hidden=!keep;if(keep)n++}document.querySelector('#count').textContent=n+' réponses affichées'}[group,verdict,search].forEach(x=>x.addEventListener('input',filter));filter();document.querySelector('#download').onclick=()=>{const blob=new Blob([document.querySelector('#data').textContent],{type:'application/json'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='bikefinder-chat-20261015.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};</script></html>'''
 replacements={'CONCLUSION':esc(review['conclusion']),'SCORE':str(satisfactory),'MEDIAN':f'{statistics.median(r["elapsed_seconds"] for r in unseen):.2f}','RAG':str(len(rag)),'COST':f'{metrics["reported_cost_usd"]:.5f}','OUTCOMES':outcomes,'ISSUES':issues,'SCREENSHOTS':screenshots,'TIMES':''.join(table),'TIMING_NOTE':esc(review['timing_note']),'CARDS':''.join(cards),'LIMITS':limits,'COMMIT':runtime['commit'][:7],'DEBIT':f'{spending["debit_usd"]:.5f}','HASH':run['questions_sha256'],'DATA':raw}
 for key,value in replacements.items():page=page.replace('__'+key+'__',value)
 assert not re.search(r'__[A-Z_]+__',page)
 out=ROOT/'docs/benchmark-chat-20261015.html';out.write_text(page);print(out);print(json.dumps(metrics,ensure_ascii=False,indent=2))
